SELECT gen_random_uuid()::text, 'formula', '$h = -\frac{B}{2A}$', 'Vertex and Focus of y = Ax² + Bx + C', '$h = -\frac{B}{2A},\quad k = C - \frac{B^2}{4A},\quad a = \frac{1}{4A}$', NULL, 'The vertex and focal distance of a vertical parabola given as a quadratic.', '[{"symbol":"$A, B, C$","meaning":"the coefficients of $y = Ax^2 + Bx + C$"},{"symbol":"$(h, k)$","meaning":"vertex"},{"symbol":"$a$","meaning":"vertex to focus"}]'::jsonb, 'The focus is $(h, k + a)$; $A > 0$ opens up.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'parabola' AND s."active"), 'Parts', true, 'PENDING', now(), now()
