SELECT gen_random_uuid()::text, 'formula', '$\frac{x^2}{a^2} + \frac{y^2}{b^2}$', 'Standard Equation of an Ellipse', '$\frac{(x - h)^2}{a^2} + \frac{(y - k)^2}{b^2} = 1,\quad a > b$', NULL, 'An ellipse with a horizontal major axis; swap a² to the y term for a vertical one.', '[{"symbol":"$(h, k)$","meaning":"the centre (or vertex)"},{"symbol":"$a, b$","meaning":"the semi-major and semi-minor axes (ellipse), or the semi-transverse and semi-conjugate axes (hyperbola)"}]'::jsonb, 'The larger denominator is a² and names the major axis.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'ellipse' AND s."active"), 'Equation', true, 'PENDING', now(), now()
