SELECT gen_random_uuid()::text, 'formula', '$c^2 = a^2 - b^2$', 'Foci and Eccentricity of an Ellipse', '$c^2 = a^2 - b^2,\quad e = \frac{c}{a} < 1$', NULL, 'Where the foci are, and how flat the ellipse is.', '[{"symbol":"$a, b$","meaning":"the semi-major and semi-minor axes (ellipse), or the semi-transverse and semi-conjugate axes (hyperbola)"},{"symbol":"$c$","meaning":"centre to focus"},{"symbol":"$e$","meaning":"eccentricity"}]'::jsonb, 'e near 0 is nearly a circle; near 1, long and thin.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'ellipse' AND s."active"), 'Foci', true, 'PENDING', now(), now()
