SELECT gen_random_uuid()::text, 'formula', '$\frac{x^2}{a^2} - \frac{y^2}{b^2}$', 'Standard Equation of a Hyperbola', '$\frac{(x - h)^2}{a^2} - \frac{(y - k)^2}{b^2} = 1$', NULL, 'A hyperbola opening left and right; the positive term names the transverse axis.', '[{"symbol":"$(h, k)$","meaning":"the centre (or vertex)"},{"symbol":"$a, b$","meaning":"the semi-major and semi-minor axes (ellipse), or the semi-transverse and semi-conjugate axes (hyperbola)"}]'::jsonb, 'Unlike the ellipse, a may be smaller than b: the sign decides, not the size.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'hyperbola' AND s."active"), 'Equation', true, 'PENDING', now(), now()
