SELECT gen_random_uuid()::text, 'formula', '$|PF_1 - PF_2| = 2a$', 'Difference of Focal Distances', '$|PF_1 - PF_2| = 2a$', NULL, 'The definition of a hyperbola: the focal distances differ by the transverse axis.', '[{"symbol":"$P$","meaning":"any point on the hyperbola"},{"symbol":"$F_1, F_2$","meaning":"the foci"},{"symbol":"$a$","meaning":"semi-transverse axis"}]'::jsonb, 'This is how LORAN-type navigation fixes a position from two time differences.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'hyperbola' AND s."active"), 'Foci', true, 'PENDING', now(), now()
