SELECT gen_random_uuid()::text, 'formula', '$B^2 - 4AC$', 'Discriminant of a Conic', '$B^2 - 4AC \begin{cases} < 0 & \text{ellipse (circle if } B = 0,\ A = C) \\ = 0 & \text{parabola} \\ > 0 & \text{hyperbola} \end{cases}$', NULL, 'Which conic a second-degree equation is, from three coefficients.', '[{"symbol":"$A, B, C$","meaning":"the coefficients of $x^2$, $xy$, $y^2$"}]'::jsonb, 'Degenerate cases (a point, lines, nothing) pass the test too; check by completing the square.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'general conic sections' AND s."active"), 'Identify', true, 'PENDING', now(), now()
