SELECT gen_random_uuid()::text, 'formula', '$e = \frac{PF}{PD}$', 'Conic by Eccentricity', '$e = \frac{PF}{PD}:\quad e = 0 \text{ circle},\ 0 < e < 1 \text{ ellipse},\ e = 1 \text{ parabola},\ e > 1 \text{ hyperbola}$', NULL, 'One definition for all conics: a fixed ratio of distances to a focus and a directrix.', '[{"symbol":"$PF$","meaning":"distance from a point to the focus"},{"symbol":"$PD$","meaning":"distance from the point to the directrix"}]'::jsonb, 'The parabola sits exactly between: equal distances.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'general conic sections' AND s."active"), 'Identify', true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
