SELECT gen_random_uuid()::text, 'formula', '$x = x'' + h$', 'Translation of Axes', '$x = x'' + h,\quad y = y'' + k$', NULL, 'Moving the origin to (h, k) without turning the axes.', '[{"symbol":"$(x, y)$","meaning":"old coordinates"},{"symbol":"$(x'', y'')$","meaning":"new coordinates"},{"symbol":"$(h, k)$","meaning":"the new origin, in old coordinates"}]'::jsonb, 'Completing the square is a translation in disguise.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'translation and rotation of axes' AND s."active"), NULL, true, 'PENDING', now(), now()
