SELECT gen_random_uuid()::text, 'formula', '$x = x''\cos\theta - y''\sin\theta$', 'Rotation of Axes', '$x = x''\cos\theta - y''\sin\theta,\quad y = x''\sin\theta + y''\cos\theta$', NULL, 'Turning the axes through θ about the origin.', '[{"symbol":"$(x, y)$","meaning":"old coordinates"},{"symbol":"$(x'', y'')$","meaning":"new coordinates"},{"symbol":"$\\theta$","meaning":"the angle the axes turn, counterclockwise"}]'::jsonb, 'The reverse: $x'' = x\cos\theta + y\sin\theta$, $y'' = -x\sin\theta + y\cos\theta$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'translation and rotation of axes' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics'
