SELECT gen_random_uuid()::text, 'formula', '$\cot 2\theta$', 'Angle That Removes the xy Term', '$\cot 2\theta = \frac{A - C}{B}$', NULL, 'How far to turn the axes so the conic has no xy term.', '[{"symbol":"$A, B, C$","meaning":"the coefficients of $x^2$, $xy$, $y^2$"},{"symbol":"$\\theta$","meaning":"rotation angle, 0° to 90°"}]'::jsonb, '$A = C$ means $\theta = 45^\circ$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'translation and rotation of axes' AND s."active"), NULL, true, 'PENDING', now(), now()
