SELECT gen_random_uuid()::text, 'formula', '$A + C$', 'Invariants Under Rotation', '$A'' + C'' = A + C,\qquad B''^2 - 4A''C'' = B^2 - 4AC$', NULL, 'What a rotation leaves unchanged: so the kind of conic never changes.', '[{"symbol":"$A, B, C$","meaning":"coefficients before the rotation"},{"symbol":"$A'', B'', C''$","meaning":"after it"}]'::jsonb, 'After removing $xy$: $A''C'' = AC - \frac{B^2}{4}$, which with $A'' + C''$ gives $A''$ and $C''$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'translation and rotation of axes' AND s."active"), NULL, true, 'PENDING', now(), now()
