SELECT gen_random_uuid()::text, 'formula', '$x = r\cos\theta$', 'Polar and Rectangular Coordinates', '$x = r\cos\theta,\quad y = r\sin\theta,\quad r^2 = x^2 + y^2,\quad \tan\theta = \frac{y}{x}$', NULL, 'Changing between polar and rectangular coordinates.', '[{"symbol":"$(r, \\theta)$","meaning":"polar coordinates"},{"symbol":"$(x, y)$","meaning":"rectangular coordinates"}]'::jsonb, '$\tan^{-1}\frac{y}{x}$ gives the wrong quadrant for half the plane: check the signs of $x$ and $y$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'polar coordinates' AND s."active"), 'Conversion', true, 'PENDING', now(), now()
