SELECT gen_random_uuid()::text, 'formula', '$d$', 'Distance Between Points in Polar Form', '$d^2 = r_1^2 + r_2^2 - 2r_1 r_2\cos(\theta_2 - \theta_1)$', NULL, 'The distance between two polar points: the cosine law.', '[{"symbol":"$(r_1, \\theta_1), (r_2, \\theta_2)$","meaning":"the two points"}]'::jsonb, 'No need to convert to x and y first.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'polar coordinates' AND s."active"), 'Conversion', true, 'PENDING', now(), now()
