SELECT gen_random_uuid()::text, 'formula', '$r = \frac{ed}{1 \pm e\cos\theta}$', 'Polar Equation of a Conic', '$r = \frac{ed}{1 \pm e\cos\theta}$', NULL, 'Every conic with a focus at the pole.', '[{"symbol":"$e$","meaning":"eccentricity"},{"symbol":"$d$","meaning":"distance from the focus (the pole) to the directrix"}]'::jsonb, 'Use $\sin\theta$ when the directrix is horizontal. Read $e$ only after the constant term is made 1.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'polar coordinates' AND s."active"), 'Curves', true, 'PENDING', now(), now()
