SELECT gen_random_uuid()::text, 'formula', '$r = a\cos n\theta$', 'Polar Circles and Roses', '$r = 2a\cos\theta\ \text{(circle)},\qquad r = a\cos n\theta\ \text{(rose)}$', NULL, 'Two common polar curves: a circle through the pole, and a rose.', '[{"symbol":"$a$","meaning":"radius (circle) or petal length (rose)"},{"symbol":"$n$","meaning":"a whole number"}]'::jsonb, 'A rose has n petals when n is odd, 2n when n is even.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'polar coordinates' AND s."active"), 'Curves', true, 'PENDING', now(), now()
