SELECT gen_random_uuid()::text, 'formula', '$\cos^2\alpha + \cos^2\beta + \cos^2\gamma$', 'Direction Cosines', '$\cos\alpha = \frac{a}{\sqrt{a^2 + b^2 + c^2}},\ \ldots,\qquad \cos^2\alpha + \cos^2\beta + \cos^2\gamma = 1$', NULL, 'The direction of a line in space, as the cosines of its angles with the axes.', '[{"symbol":"$(a, b, c)$","meaning":"direction numbers of the line"},{"symbol":"$\\alpha, \\beta, \\gamma$","meaning":"the angles it makes with the $x$, $y$, $z$ axes"}]'::jsonb, 'Given two direction cosines, the third follows (up to sign).', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'lines and planes in space' AND s."active"), 'Lines', true, 'PENDING', now(), now()
