SELECT gen_random_uuid()::text, 'formula', '$(x - h)^2 + (y - k)^2 + (z - l)^2$', 'Equation of a Sphere', '$(x - h)^2 + (y - k)^2 + (z - l)^2 = r^2$', NULL, 'The sphere: the circle''s equation with a third coordinate.', '[{"symbol":"$(h, k, l)$","meaning":"centre"},{"symbol":"$r$","meaning":"radius"}]'::jsonb, 'In general form $x^2 + y^2 + z^2 + Dx + Ey + Fz + G = 0$, the centre is $\left(-\frac{D}{2}, -\frac{E}{2}, -\frac{F}{2}\right)$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Analytic Geometry' AND t."subject" = 'Mathematics' AND s."normKey" = 'lines and planes in space' AND s."active"), 'Surfaces', true, 'PENDING', now(), now()
